import hashlib
import json
import sqlite3
import time
from contextlib import contextmanager

db = sqlite3.connect("funding_ledger.sqlite3", isolation_level=None)
db.row_factory = sqlite3.Row
db.execute("PRAGMA foreign_keys = ON")
db.execute("PRAGMA journal_mode = WAL")
db.execute("PRAGMA synchronous = FULL")
db.execute("PRAGMA busy_timeout = 10000")

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"))

def digest(value):
    return hashlib.sha256(canonical(value).encode("utf-8")).hexdigest()

@contextmanager
def atomic():
    db.execute("BEGIN IMMEDIATE")
    try:
        yield
        db.execute("COMMIT")
    except BaseException:
        if db.in_transaction:
            db.execute("ROLLBACK")
        raise

db.executescript("""
CREATE TABLE IF NOT EXISTS deal (
    id INTEGER PRIMARY KEY,
    intake_key TEXT NOT NULL UNIQUE,
    payload_hash TEXT NOT NULL,
    lane TEXT NOT NULL CHECK(lane IN ('flash', 'emd')),
    principal_cents INTEGER NOT NULL CHECK(principal_cents > 0),
    fee_cents INTEGER NOT NULL CHECK(fee_cents > 0),
    state TEXT NOT NULL CHECK(
        state IN ('SCORED', 'QUEUED', 'FUNDED', 'CLOSED')
    )
);
CREATE TABLE IF NOT EXISTS outbox (
    id INTEGER PRIMARY KEY,
    deal_id INTEGER NOT NULL UNIQUE REFERENCES deal(id),
    idempotency_key TEXT NOT NULL UNIQUE,
    payload TEXT NOT NULL,
    payload_hash TEXT NOT NULL,
    expires_at INTEGER NOT NULL,
    state TEXT NOT NULL CHECK(
        state IN ('READY', 'CLAIMED', 'AMBIGUOUS', 'ACK')
    ),
    bank_ref TEXT UNIQUE
);
CREATE TABLE IF NOT EXISTS batch (
    id INTEGER PRIMARY KEY,
    operation_key TEXT NOT NULL UNIQUE,
    external_ref TEXT NOT NULL UNIQUE,
    payload_hash TEXT NOT NULL,
    deal_id INTEGER REFERENCES deal(id),
    posted INTEGER NOT NULL DEFAULT 0 CHECK(posted IN (0, 1))
);
CREATE TABLE IF NOT EXISTS entry (
    batch_id INTEGER NOT NULL REFERENCES batch(id),
    line_no INTEGER NOT NULL,
    account TEXT NOT NULL CHECK(account IN (
        'cash', 'receivable', 'earned_fees', 'expense', 'owner_capital'
    )),
    cents INTEGER NOT NULL CHECK(cents != 0),
    PRIMARY KEY(batch_id, line_no)
);
CREATE TRIGGER IF NOT EXISTS batch_start_draft
BEFORE INSERT ON batch WHEN NEW.posted != 0
BEGIN SELECT RAISE(ABORT, 'batch must begin as draft'); END;
CREATE TRIGGER IF NOT EXISTS batch_balance
BEFORE UPDATE OF posted ON batch
WHEN NEW.posted = 1 AND (
    (SELECT COUNT(*) FROM entry WHERE batch_id = OLD.id) < 2
    OR COALESCE(
        (SELECT SUM(cents) FROM entry WHERE batch_id = OLD.id), 0
    ) != 0
)
BEGIN SELECT RAISE(ABORT, 'unbalanced batch'); END;
CREATE TRIGGER IF NOT EXISTS batch_lock_update
BEFORE UPDATE ON batch WHEN OLD.posted = 1
BEGIN SELECT RAISE(ABORT, 'posted batch is immutable'); END;
CREATE TRIGGER IF NOT EXISTS batch_lock_delete
BEFORE DELETE ON batch WHEN OLD.posted = 1
BEGIN SELECT RAISE(ABORT, 'posted batch is immutable'); END;
CREATE TRIGGER IF NOT EXISTS entry_lock_insert
BEFORE INSERT ON entry
WHEN (SELECT posted FROM batch WHERE id = NEW.batch_id) = 1
BEGIN SELECT RAISE(ABORT, 'posted entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS entry_lock_update
BEFORE UPDATE ON entry
BEGIN SELECT RAISE(ABORT, 'replace draft lines by rebuilding batch'); END;
CREATE TRIGGER IF NOT EXISTS entry_lock_delete
BEFORE DELETE ON entry
WHEN (SELECT posted FROM batch WHERE id = OLD.batch_id) = 1
BEGIN SELECT RAISE(ABORT, 'posted entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS outbox_payload_lock
BEFORE UPDATE OF deal_id, idempotency_key, payload,
                 payload_hash, expires_at ON outbox
BEGIN SELECT RAISE(ABORT, 'payment payload is immutable'); END;
""")

def intake(intake_key, lane, principal_cents, fee_cents):
    if not isinstance(intake_key, str) or not intake_key:
        raise ValueError("intake key required")
    if lane not in ("flash", "emd"):
        raise ValueError("unsupported production lane")
    if type(principal_cents) is not int or type(fee_cents) is not int:
        raise ValueError("integer cents required")
    if not 0 < principal_cents <= 4000000 or fee_cents <= 0:
        raise ValueError("ticket outside approved production limits")
    packet = {
        "lane": lane,
        "principal_cents": principal_cents,
        "fee_cents": fee_cents,
    }
    fingerprint = digest(packet)
    with atomic():
        previous = db.execute(
            "SELECT id, payload_hash FROM deal WHERE intake_key = ?",
            (intake_key,),
        ).fetchone()
        if previous:
            if previous["payload_hash"] != fingerprint:
                raise ValueError("conflicting intake key reuse")
            return previous["id"]
        cursor = db.execute(
            """INSERT INTO deal
               (intake_key, payload_hash, lane, principal_cents,
                fee_cents, state)
               VALUES (?, ?, ?, ?, ?, 'SCORED')""",
            (intake_key, fingerprint, lane, principal_cents, fee_cents),
        )
        return cursor.lastrowid

def claim():
    with atomic():
        row = db.execute(
            """SELECT * FROM outbox
               WHERE state = 'READY' AND expires_at > ?
               ORDER BY id LIMIT 1""",
            (int(time.time()),),
        ).fetchone()
        if row is None:
            return None
        db.execute(
            "UPDATE outbox SET state = 'CLAIMED' WHERE id = ?",
            (row["id"],),
        )
        return dict(row)

def confirm_draw(key, bank_ref):
    if not isinstance(bank_ref, str) or not bank_ref.strip():
        raise ValueError("final verified bank reference required")
    with atomic():
        row = db.execute(
            """SELECT o.*, d.principal_cents FROM outbox o
               JOIN deal d ON d.id = o.deal_id
               WHERE o.idempotency_key = ?""",
            (key,),
        ).fetchone()
        if not row:
            raise ValueError("payment key does not exist")
        if row["state"] == "ACK":
            if row["bank_ref"] != bank_ref:
                raise ValueError("conflicting bank confirmation")
            return
        if row["state"] not in ("CLAIMED", "AMBIGUOUS"):
            raise ValueError("payment was never dispatched")
        _post(
            "draw:" + str(row["deal_id"]),
            "bank:" + bank_ref,
            row["deal_id"],
            [
                ("receivable", row["principal_cents"]),
                ("cash", -row["principal_cents"]),
            ],
        )
        db.execute(
            "UPDATE outbox SET state = 'ACK', bank_ref = ? WHERE id = ?",
            (bank_ref, row["id"]),
        )
        db.execute(
            "UPDATE deal SET state = 'FUNDED' WHERE id = ?",
            (row["deal_id"],),
        )

def dispatch_one(send):
    row = claim()
    if row is None:
        return False
    try:
        if int(time.time()) >= row["expires_at"]:
            raise RuntimeError("verification expired before submission")
        actual = hashlib.sha256(row["payload"].encode("utf-8")).hexdigest()
        if actual != row["payload_hash"]:
            raise RuntimeError("payment payload integrity failure")
        bank_ref = send(
            idempotency_key=row["idempotency_key"],
            payload=json.loads(row["payload"]),
            expires_at=row["expires_at"],
        )
        confirm_draw(row["idempotency_key"], bank_ref)
    except BaseException:
        with atomic():
            db.execute(
                """UPDATE outbox SET state = 'AMBIGUOUS'
                   WHERE id = ? AND state = 'CLAIMED'""",
                (row["id"],),
            )
        raise
    return True

def _post(operation_key, external_ref, deal_id, lines):
    if not db.in_transaction:
        raise RuntimeError("posting requires an active write transaction")
    if len(lines) < 2 or any(
        type(cents) is not int or cents == 0 for account, cents in lines
    ):
        raise ValueError("nonzero integer journal lines required")
    if sum(cents for account, cents in lines) != 0:
        raise ValueError("journal does not balance")
    fingerprint = digest({
        "external_ref": external_ref,
        "deal_id": deal_id,
        "lines": lines,
    })
    prior = db.execute(
        "SELECT id, payload_hash, posted FROM batch WHERE operation_key = ?",
        (operation_key,),
    ).fetchone()
    if prior:
        if prior["payload_hash"] != fingerprint or prior["posted"] != 1:
            raise ValueError("conflicting accounting event")
        return prior["id"]
    cursor = db.execute(
        """INSERT INTO batch
           (operation_key, external_ref, payload_hash, deal_id)
           VALUES (?, ?, ?, ?)""",
        (operation_key, external_ref, fingerprint, deal_id),
    )
    batch_id = cursor.lastrowid
    db.executemany(
        "INSERT INTO entry(batch_id, line_no, account, cents) VALUES (?, ?, ?, ?)",
        [
            (batch_id, number, account, cents)
            for number, (account, cents) in enumerate(lines, 1)
        ],
    )
    db.execute("UPDATE batch SET posted = 1 WHERE id = ?", (batch_id,))
    return batch_id

def settle(deal_id, bank_ref, cash_cents, earned_cents):
    if type(cash_cents) is not int or type(earned_cents) is not int:
        raise ValueError("integer settlement amounts required")
    if not bank_ref:
        raise ValueError("verified return reference required")
    with atomic():
        deal = db.execute(
            "SELECT * FROM deal WHERE id = ?", (deal_id,)
        ).fetchone()
        if not deal or deal["state"] not in ("FUNDED", "CLOSED"):
            raise ValueError("deal is not eligible for settlement")
        if not 0 <= earned_cents <= deal["fee_cents"]:
            raise ValueError("earned fee exceeds contracted fee")
        if cash_cents != deal["principal_cents"] + earned_cents:
            raise ValueError("partial returns require reviewed exception posting")
        lines = [
            ("cash", cash_cents),
            ("receivable", -deal["principal_cents"]),
        ]
        if earned_cents:
            lines.append(("earned_fees", -earned_cents))
        _post(
            "return:" + str(deal_id), "bank:" + bank_ref, deal_id, lines
        )
        db.execute(
            "UPDATE deal SET state = 'CLOSED' WHERE id = ?", (deal_id,)
        )

def record_broker_fee(service_ref, bank_ref, earned_cents):
    if not service_ref or not bank_ref:
        raise ValueError("service evidence and bank reference required")
    if type(earned_cents) is not int or earned_cents <= 0:
        raise ValueError("positive earned compensation required")
    with atomic():
        return _post(
            "broker:" + service_ref, "bank:" + bank_ref, None,
            [("cash", earned_cents), ("earned_fees", -earned_cents)],
        )

db.executescript("""
CREATE VIEW IF NOT EXISTS reconciliation AS
SELECT d.id, d.state,
       COALESCE(SUM(CASE WHEN e.account = 'receivable'
                        THEN e.cents ELSE 0 END), 0) AS principal_open,
       COALESCE(SUM(CASE WHEN e.account = 'cash'
                        THEN e.cents ELSE 0 END), 0) AS net_cash,
       -COALESCE(SUM(CASE WHEN e.account = 'earned_fees'
                         THEN e.cents ELSE 0 END), 0) AS earned_fees
FROM deal d
LEFT JOIN batch b ON b.deal_id = d.id AND b.posted = 1
LEFT JOIN entry e ON e.batch_id = b.id
GROUP BY d.id, d.state;
CREATE VIEW IF NOT EXISTS trial_balance AS
SELECT e.account, SUM(e.cents) AS balance_cents
FROM entry e JOIN batch b ON b.id = e.batch_id
WHERE b.posted = 1
GROUP BY e.account;
""")
